import { Injectable, computed, signal } from '@angular/core';

export interface CartItem {
  id: number;
  name: string;
  price: number;
}

@Injectable({ providedIn: 'root' })
export class CartService {
  private readonly items = signal<CartItem[]>([]);

  readonly list = this.items.asReadonly();
  readonly count = computed(() => this.items().length);
  readonly total = computed(() => this.items().reduce((sum, item) => sum + item.price, 0));

  add(item: CartItem): void {
    this.items.update((list) => [...list, item]);
  }

  remove(id: number): void {
    this.items.update((list) => list.filter((item) => item.id !== id));
  }
}

import { Component, inject } from '@angular/core';
import { CartService } from '../cart-service';

@Component({
  selector: 'app-product',
  template: `<button (click)="buy()">Buy keyboard (49)</button>`,
})
export class Product {
  private readonly cart = inject(CartService);

  buy(): void {
    this.cart.add({ id: Date.now(), name: 'Keyboard', price: 49 });
  }
}

@Component({
  selector: 'app-cart-badge',
  template: `<span>Cart: {{ cart.count() }} items, {{ cart.total() }} EUR</span>`,
})
export class CartBadge {
  protected readonly cart = inject(CartService);
}

